import { httpAjax } from './httpAjax/index.js'
import { channels } from './channels/index.js'


let chRoot, rootElement, loader, pauseElement, nameTrack, audio, hasTouch, radar, radioStations, btnPlay, btnStop, nameElement;

hasTouch = window.matchMedia('(pointer: coarse)').matches;



audio = new Audio();
const mainPromise = new Promise((resolve, reject) => resolve(httpAjax("GET", "../../stations.json", "json")));
mainPromise
    .then(data => {
        let completeData = data[0];
        audio.crossOrigin = 'anonymous';
        audio.src = completeData.url
        nameElement = document.querySelector('.name')
        nameTrack = document.querySelector('.track')
        btnPlay = document.querySelector('.btn-play')
        radar = document.querySelector('#radar')
        nameElement.innerHTML = completeData.name
        // nameTrack =
        readRadioTrack(completeData.url, (title) => nameTrack.innerHTML = title)
            .catch(console.error);


        return btnPlay;
    })
    .then(data => {
        data.addEventListener('click', () => {
            audio.play()


        })
        btnStop = document.querySelector('.btn-stop')
        return btnStop;
    })
    .then(data => {
        data.addEventListener('click', () => {
            audio.pause();
        })
    })
    .catch(error => {
        console.log(error);

    })
    .finally(() => {
    })


const fullscreenBtn = document.getElementById('fullscreen-btn');

fullscreenBtn.addEventListener('click', async () => {
    try {
        if (document.fullscreenElement) {
            await document.exitFullscreen();
        } else {
            await document.documentElement.requestFullscreen();
        }
    } catch (error) {
        console.error('Error Full Screen:', error);
    }
});

document.addEventListener('fullscreenchange', () => {
    fullscreenBtn.textContent = document.fullscreenElement
        ? 'Out Full Screen'
        : 'Full Screen';
});



async function readRadioTrack(url, onTrack) {
    const response = await fetch(url, {
        headers: { 'Icy-MetaData': '1' }
    });

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let text = '';
    let previousTitle = null;

    try {
        while (true) {
            const { value, done } = await reader.read();
            if (done) break;

            text += decoder.decode(value, { stream: true });

            let match;

            while ((match = text.match(/StreamTitle='([\s\S]*?)';/))) {
                const title = match[1];

                if (title !== previousTitle) {
                    previousTitle = title;
                    onTrack(title);
                }

                text = text.slice(match.index + match[0].length);
            }

            text = text.slice(-65536);
        }
    } finally {
        await reader.cancel();
    }
}



